#include <iostream>
#include <vector>
#include <cassert>
using namespace std;

struct MatrixType {
    int height, width;
    vector<long long> elements;
    MatrixType(int r=0,int c=0):height(r),width(c),elements(r*c){}
    long long& val(int r,int c){return elements[r*width+c];}
    long long val(int r,int c)const{return elements[r*width+c];}
    MatrixType& add(const MatrixType& m){
        assert(height==m.height && width==m.width);
        for(int i=0;i<height*width;++i)elements[i]+=m.elements[i];
        return *this;
    }
    MatrixType& subtract(const MatrixType& m){
        assert(height==m.height && width==m.width);
        for(int i=0;i<height*width;++i)elements[i]-=m.elements[i];
        return *this;
    }
    MatrixType& multiply(const MatrixType& m){
        assert(width==m.height);
        MatrixType result(height,m.width);
        for(int i=0;i<height;++i){
            for(int j=0;j<m.width;++j){
                for(int k=0;k<width;++k){
                    result.val(i,j)+=val(i,k)*m.val(k,j)%mod;
                }
                result.val(i,j)%=mod;
            }
        }
        *this=result;
        return *this;
    }
    static MatrixType identity(int n){
        MatrixType res(n,n);
        for(int i=0;i<n;++i)res.val(i,i)=1;
        return res;
    }
    static MatrixType power(MatrixType a,int n){
        assert(a.height==a.width);
        MatrixType res=identity(a.height);
        while(n){
            if(n&1)res.multiply(a);
            a.multiply(a);
            n>>=1;
        }
        return res;
    }
};

vector<MatrixType> matrices(65);
long long compute(int i,int k){
    return MatrixType::power(matrices[i+k],k-i)*MatrixType::power(matrices[i],i);
}

long long main_solve(long long n,long long k){
    long long count=0,tmp=n;
    while(tmp){tmp/=k;++count;}
    vector<MatrixType> b(count+5),c(count+5),d(k+1);
    b[0]=matrices[k-1];
    c[0]=MatrixType::power(b[0],k-1);
    b[1]=compute(k-1,k);
    c[1]=MatrixType::power(b[1],k-1);
    MatrixType s=MatrixType::identity(2*k+1);
    for(int j=2;j<=count+1;++j){
        b[j]=compute(k-j%k,k);
        s*=c[j-1];
        b[j]*=s;
        c[j]=MatrixType::power(b[j],k-1);
    }
    int idx=1,rem=n%k;
    n-=rem;
    int q=0;
    long long tmp2=n;
    if(tmp2){while(tmp2%k==0){++q;tmp2/=k;}}
    q=(k-q%k)%k;
    MatrixType ans=MatrixType::identity(2*k+1);
    ans=MatrixType::power(matrices[q],rem)*MatrixType::power(matrices[q+k],max(rem-q,0));
    n/=k;
    if(n==0){return (ans.val(2*k,0)+ans.val(0,0))%mod;}
    --n;
    while(n){
        int t=n%k;
        if(t){ans*=MatrixType::power(b[idx],t);}
        n/=k;++idx;
    }
    ans*=b[1];
    return (ans.val(2*k,0)+ans.val(0,0))%mod;
}

int main(){
    long long n,k;
    cin>>n>>k;
    for(int i=0;i<=2*k;++i){
        matrices[i]=MatrixType(2*k+1);
        for(int j=0;j<i;++j)matrices[i].val(0,j)=1;
        for(int j=0;j<2*k-1;++j)matrices[i].val(j+1,j)=1;
        matrices[i].val(2*k,0)=1;
        matrices[i].val(2*k,2*k)=1;
    }
    cout<<main_solve(n,k)<<endl;
    return 0;
}
